insert into public.assessment_test_definitions (workspace_id, test_key, version, name, kind, definition) values
  (null, 'overhead_squat', 1, 'Overhead squat', 'scored', $def${"key":"overhead_squat","version":1,"name":"Overhead squat","summary":"Front + side · shoes on","kind":"scored","steps":["Shoes on, feet hip-width, toes forward","Arms straight overhead, no dowel","Squat slowly a few times"],"views":[{"id":"front","label":"Front","watch":"Front: feet, knees, hips","groups":[{"label":"Feet","checkpoints":[{"id":"ohs.feet_turn_out","label":"Turn out","finding":"Feet turn out","sided":true,"guide":{"slight":"Toes turn out a little","severe":"Toes turn clearly out"}},{"id":"ohs.heel_rise","label":"Heels lift","sided":true,"guide":{"slight":"Heel lifts a little, weight onto the toes","severe":"Heel clearly off the floor"}}]},{"label":"Knees","checkpoints":[{"id":"ohs.knee_valgus","label":"Cave in (valgus)","finding":"Knees cave in","sided":true,"guide":{"slight":"Knee moves inward but stays over the foot","severe":"Knee moves inside the big toe"}},{"id":"ohs.knee_varus","label":"Bow out","finding":"Knees bow out","sided":true,"guide":{"slight":"Knee moves a little outside the foot","severe":"Knee moves outside the little toe"}}]},{"label":"Hips","checkpoints":[{"id":"ohs.weight_shift","label":"Shift to one side","finding":"Shifts to one side","sided":true,"guide":{"slight":"Small shift toward this side","severe":"Clear shift toward this side"}}]}]},{"id":"side","label":"Side","watch":"Side: trunk, arms, head","groups":[{"label":"Trunk","checkpoints":[{"id":"ohs.forward_lean","label":"Leans forward","sided":false,"guide":{"slight":"Trunk a little more forward than the shins","severe":"Chest drops toward the thighs"}},{"id":"ohs.low_back_arch","label":"Low back arches","sided":false,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}}]},{"label":"Shoulders","checkpoints":[{"id":"ohs.arms_fall_forward","label":"Arms fall forward","sided":true,"guide":{"slight":"Arms drift a little in front of the ears","severe":"Arms drop well forward of the trunk line"}}]},{"label":"Head","checkpoints":[{"id":"ohs.head_forward","label":"Pokes forward","finding":"Head pokes forward","sided":false,"guide":{"slight":"Chin a little forward","severe":"Chin clearly forward of the chest"}}]}]}],"measures":[],"followUps":[{"id":"ohs.heel_lift_retest","label":"Heel-lift follow-up","prompt":"Squat again with heels on a small lift. Knees and arms:","after":"ohs.heel_rise","options":[{"value":"better","label":"Better"},{"value":"same","label":"Same"}]}],"sources":["Post EG et al. 2017, J Sport Rehabil 26(1):18-23 (overhead squat, knee displacement)","Bell DR, Padua DA, Clark MA 2008, Arch Phys Med Rehabil 89(7):1323-8 (medial knee displacement)","Macrum E et al. 2012, J Sport Rehabil 21(2):144-50 (ankle range and knee valgus)"]}$def$::jsonb),
  (null, 'single_leg_squat', 1, 'Single-leg squat', 'scored', $def${"key":"single_leg_squat","version":1,"name":"Single-leg squat","summary":"Each leg · front","kind":"scored","steps":["Stand on one leg, arms crossed","Squat to about a quarter squat, slowly, a few times","Then the other leg"],"views":[{"id":"front","label":"Front","watch":"Front: trunk, hips, knee, foot","groups":[{"label":"Knees","checkpoints":[{"id":"sls.knee_valgus","label":"Knee caves in","sided":true,"guide":{"slight":"Knee moves inward but stays over the foot","severe":"Knee moves inside the big toe"}}]},{"label":"Hips","checkpoints":[{"id":"sls.pelvic_drop","label":"Opposite hip drops","sided":true,"guide":{"slight":"Opposite hip drops a little","severe":"Opposite hip drops clearly"}}]},{"label":"Trunk","checkpoints":[{"id":"sls.trunk_lateral_lean","label":"Trunk leans sideways","sided":true,"guide":{"slight":"Small lean over the standing leg","severe":"Clear lean over the standing leg"}}]},{"label":"Feet","checkpoints":[{"id":"sls.foot_collapse","label":"Arch collapses","sided":true,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}},{"id":"sls.loses_balance","label":"Loses balance","sided":true,"guide":{"slight":"Wobbles but stays up","severe":"Foot touches down or grabs for support"}}]}]}],"measures":[],"followUps":[],"sources":["Crossley KM et al. 2011, Am J Sports Med 39(4):866-73 (single-leg squat rating)"]}$def$::jsonb),
  (null, 'push_up', 1, 'Push-up', 'scored', $def${"key":"push_up","version":1,"name":"Push-up","summary":"Side view · note the type done","kind":"scored","steps":["Side view","A few slow reps"],"views":[{"id":"side","label":"Side","watch":"Side: trunk, shoulders, head","groups":[{"label":"Trunk","checkpoints":[{"id":"pu.lumbar_sag","label":"Hips sag","sided":false,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}},{"id":"pu.hip_pike","label":"Hips pike up","sided":false,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}}]},{"label":"Shoulders","checkpoints":[{"id":"pu.scapular_winging","label":"Shoulder blades wing","sided":true,"guide":{"slight":"Slight lift, not on every rep","severe":"Clear lift on most reps"}},{"id":"pu.scapular_elevation","label":"Shoulders shrug","sided":true,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}}]},{"label":"Head","checkpoints":[{"id":"pu.head_forward","label":"Chin pokes forward","sided":false,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}}]}]}],"measures":[],"followUps":[],"typeDone":{"label":"Type done","placeholder":"Floor, incline (hands on bench) or knees"},"sources":["McClure P et al. 2009, J Athl Train 44(2):160-4 (scapular dyskinesis, visual rating)"]}$def$::jsonb),
  (null, 'shoulder_mobility', 1, 'Shoulder mobility', 'scored', $def${"key":"shoulder_mobility","version":1,"name":"Shoulder mobility","summary":"Measure each side","kind":"scored","steps":["Fists behind back, one from above, one from below","Measure the gap","Swap arms"],"views":[{"id":"back","label":"Back","watch":"Watch: shoulder hiking, discomfort","groups":[{"label":"Also seen","checkpoints":[{"id":"shm.shoulder_hike","label":"Shoulder hikes up","sided":true,"guide":{"slight":"Shoulder lifts a little","severe":"Shoulder lifts clearly toward the ear"}}]}]}],"measures":[{"id":"shm.reach_gap","label":"Shoulder mobility gap · top hand","unit":"cm","sided":true,"higherIsBetter":false,"min":0,"max":60}],"followUps":[],"sources":["Cook G et al. 2014, Int J Sports Phys Ther 9(3):396-409 (FMS shoulder mobility)"]}$def$::jsonb),
  (null, 'active_straight_leg_raise', 1, 'Straight-leg raise', 'scored', $def${"key":"active_straight_leg_raise","version":1,"name":"Straight-leg raise","summary":"Measure each side","kind":"scored","steps":["Lie on back, legs straight","Lift one straight leg as high as you can","Measure the angle, then swap"],"views":[{"id":"side","label":"Side","watch":"Side: the other leg and the pelvis","groups":[{"label":"Also seen","checkpoints":[{"id":"aslr.down_leg_moves","label":"Other leg lifts or bends","sided":true,"guide":{"slight":"Other leg lifts or bends a little","severe":"Other leg clearly lifts, bends or rolls out"}},{"id":"aslr.pelvis_moves","label":"Pelvis tilts or rotates","sided":true,"guide":{"slight":"Seen on some reps or small in size","severe":"Seen on most reps and clearly visible"}}]}]}],"measures":[{"id":"aslr.angle","label":"Straight-leg raise","unit":"deg","sided":true,"higherIsBetter":true,"min":0,"max":120}],"followUps":[],"sources":["Cook G et al. 2014, Int J Sports Phys Ther 9(3):396-409 (FMS active straight-leg raise)"]}$def$::jsonb),
  (null, 'static_posture', 1, 'Posture', 'record_only', $def${"key":"static_posture","version":1,"name":"Posture","summary":"Checklist · record only","kind":"record_only","steps":["Relaxed standing, front and side"],"views":[{"id":"side","label":"Side","watch":"Relaxed standing, front and side","groups":[{"label":"Checklist · record only","checkpoints":[{"id":"posture.head_forward","label":"Head forward","sided":false,"guide":{"slight":"Ear a little in front of the shoulder","severe":"Ear clearly in front of the shoulder"}},{"id":"posture.rounded_shoulders","label":"Rounded shoulders","sided":true,"guide":{"slight":"A little forward","severe":"Clearly forward"}},{"id":"posture.shoulder_higher","label":"One shoulder higher","sided":true,"guide":{"slight":"A little higher","severe":"Clearly higher"}},{"id":"posture.low_back_arch","label":"Low back arches","sided":false,"guide":{"slight":"A little more curve","severe":"Clearly more curve"}},{"id":"posture.knees_lock_back","label":"Knees lock back","sided":true,"guide":{"slight":"A little past straight","severe":"Clearly past straight"}},{"id":"posture.feet_roll_in","label":"Feet roll in","sided":true,"guide":{"slight":"Heel rolls in a little","severe":"Heel clearly rolled in"}}]}]}],"measures":[],"followUps":[],"sources":["Content draft 2026-11-20, static posture: record only, not linked to muscles on its own"]}$def$::jsonb),
  (null, 'side_lying_hip_hold', 1, 'Side-lying hip hold', 'scored', $def${"key":"side_lying_hip_hold","version":1,"name":"Side-lying hip hold","summary":"Hold each side","kind":"scored","steps":["Lie on your side, bottom knee bent, body in a straight line","Lift the top leg straight, slightly behind you, toes forward","Hold as long as form stays (stop at 2 min), then swap"],"views":[{"id":"back","label":"Back","watch":"From behind: top hip and leg","groups":[{"label":"Hips","checkpoints":[{"id":"slhh.hip_rolls_back","label":"Hip rolls back","sided":true,"guide":{"slight":"Top hip rolls back a little","severe":"Top hip clearly rolls back"}},{"id":"slhh.leg_drifts_forward","label":"Leg drifts forward","sided":true,"guide":{"slight":"Leg drifts a little in front of the body","severe":"Leg clearly in front of the body"}},{"id":"slhh.hip_hikes","label":"Hip hikes up","sided":true,"guide":{"slight":"Top hip moves a little toward the ribs","severe":"Top hip clearly hitched toward the ribs"}}]},{"label":"Feet","checkpoints":[{"id":"slhh.toes_turn_up","label":"Toes turn up","sided":true,"guide":{"slight":"Toes turn up a little","severe":"Toes point clearly up"}}]}]}],"measures":[{"id":"slhh.hold_time","label":"Hold time · top leg","unit":"s","sided":true,"higherIsBetter":true,"min":0,"max":120}],"followUps":[],"sources":["Distefano LJ et al. 2009, J Orthop Sports Phys Ther 39(7):532-40 (side-lying hip abduction: high gluteus medius activity)","Selkowitz DM et al. 2013, J Orthop Sports Phys Ther 43(2):54-64 (gluteal vs TFL activity; hip rolling back and flexing recruits TFL)"],"needsReview":true}$def$::jsonb),
  (null, 'wall_shoulder_flexion', 1, 'Wall shoulder flexion', 'scored', $def${"key":"wall_shoulder_flexion","version":1,"name":"Wall shoulder flexion","summary":"Each side","kind":"scored","steps":["Back, head and bottom on the wall, feet a small step out","Low back flat on the wall","Raise straight arms overhead toward the wall, thumbs back","Measure thumb to wall"],"views":[{"id":"side","label":"Side","watch":"Side: low back, elbows, shoulders","groups":[{"label":"Trunk","checkpoints":[{"id":"wsf.low_back_arch","label":"Low back leaves the wall","sided":false,"guide":{"slight":"Small gap opens","severe":"Clear arch, ribs flare"}}]},{"label":"Shoulders","checkpoints":[{"id":"wsf.elbow_bend","label":"Elbow bends","sided":true,"guide":{"slight":"Elbow bends a little","severe":"Elbow clearly bent"}},{"id":"wsf.arm_drifts_out","label":"Arm drifts out","sided":true,"guide":{"slight":"Arm drifts a little to the side","severe":"Arm clearly out to the side"}},{"id":"wsf.shoulder_hike","label":"Shoulder hikes up","sided":true,"guide":{"slight":"Shoulder lifts a little","severe":"Shoulder lifts clearly toward the ear"}}]}]}],"measures":[{"id":"wsf.gap","label":"Thumb-to-wall gap","unit":"cm","sided":true,"higherIsBetter":false,"min":0,"max":40}],"followUps":[],"sources":["Kendall FP et al. 2005, Muscles: Testing and Function with Posture and Pain, 5th ed. (shoulder flexor / latissimus length test)"],"needsReview":true}$def$::jsonb),
  (null, 'seated_hip_internal_rotation', 1, 'Seated hip internal rotation', 'scored', $def${"key":"seated_hip_internal_rotation","version":1,"name":"Seated hip internal rotation","summary":"Measure each side","kind":"scored","steps":["Sit tall on the edge of a bench, knees bent at 90°","Keep the thigh still, swing the foot out to the side","Measure the shin angle from vertical, then swap"],"views":[{"id":"front","label":"Front","watch":"Front: trunk, hips, thigh","groups":[{"label":"Also seen","checkpoints":[{"id":"hir.trunk_lean","label":"Hip lifts or trunk leans","sided":true,"guide":{"slight":"Small lean or hip lift","severe":"Clear lean, hip off the bench"}},{"id":"hir.thigh_moves","label":"Thigh moves","sided":true,"guide":{"slight":"Knee slides a little","severe":"Knee clearly moves in or out"}}]}]}],"measures":[{"id":"hir.angle","label":"Internal rotation","unit":"deg","sided":true,"higherIsBetter":true,"min":0,"max":70}],"followUps":[],"sources":["Ellison JB, Rose SJ, Sahrmann SA 1990, Phys Ther 70(9):537-541 (hip rotation range, sitting)","Norkin CC, White DJ, Measurement of Joint Motion: A Guide to Goniometry (hip internal rotation, seated)"],"needsReview":true}$def$::jsonb);
